func Test_MixedSetOperations(t *testing.T) {
	// Test mixing thread-safe and thread-unsafe sets
	safeSet := NewSet[int]()
	unsafeSet := NewThreadUnsafeSet[int]()

	safeSet.Add(1, 2, 3)
	unsafeSet.Add(3, 4, 5)

	// Test ContainsAnyElement
	if !safeSet.ContainsAnyElement(unsafeSet) {
		t.Error("safeSet should contain elements from unsafeSet (both have 3)")
	}

	if !unsafeSet.ContainsAnyElement(safeSet) {
		t.Error("unsafeSet should contain elements from safeSet (both have 3)")
	}

	// Test Equal
	unequalUnsafeSet := NewThreadUnsafeSet[int]()
	unequalUnsafeSet.Add(6, 7, 8)
	if safeSet.Equal(unequalUnsafeSet) {
		t.Error("safeSet and unequalUnsafeSet should not be equal")
	}

	equalUnsafeSet := NewThreadUnsafeSet[int]()
	equalUnsafeSet.Add(1, 2, 3)
	if !safeSet.Equal(equalUnsafeSet) {
		t.Error("safeSet and equalUnsafeSet should be equal")
	}

	// Test IsSubset
	subsetUnsafeSet := NewThreadUnsafeSet[int]()
	subsetUnsafeSet.Add(1, 2)
	if !subsetUnsafeSet.IsSubset(safeSet) {
		t.Error("subsetUnsafeSet should be a subset of safeSet")
	}

	// Test Union
	unionResult := safeSet.Union(unsafeSet)
	expectedCardinality := 5 // {1, 2, 3, 4, 5}
	if unionResult.Cardinality() != expectedCardinality {
		t.Errorf("Union should have %d elements, but has %d", expectedCardinality, unionResult.Cardinality())
	}

	// Test Intersect
	intersectResult := safeSet.Intersect(unsafeSet)
	expectedIntersectCardinality := 1 // {3}
	if intersectResult.Cardinality() != expectedIntersectCardinality {
		t.Errorf("Intersect should have %d elements, but has %d", expectedIntersectCardinality, intersectResult.Cardinality())
	}

	// Test Difference
	differenceResult := safeSet.Difference(unsafeSet)
	expectedDifferenceCardinality := 2 // {1, 2}
	if differenceResult.Cardinality() != expectedDifferenceCardinality {
		t.Errorf("Difference should have %d elements, but has %d", expectedDifferenceCardinality, differenceResult.Cardinality())
	}

	// Test SymmetricDifference
	symDiffResult := safeSet.SymmetricDifference(unsafeSet)
	expectedSymDiffCardinality := 4 // {1, 2, 4, 5}
	if symDiffResult.Cardinality() != expectedSymDiffCardinality {
		t.Errorf("SymmetricDifference should have %d elements, but has %d", expectedSymDiffCardinality, symDiffResult.Cardinality())
	}
}
EOF
